INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Ausbildungsordnung für alle Berufe gleich?', 2, '[{"text": "Nein", "correct": true, "because": "Berufsspezifisch geregelt"}, {"text": "Ja", "correct": false, "because": "Unterschiedlich je Beruf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Ausbildungsordnung?', 3, '[{"text": "Einheitliche Ausbildung sichern", "correct": true, "because": "Standardisiert Inhalte"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Produktivität steigern", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Ausbildungsordnung?', 5, '[{"text": "Ausbildungsrahmenplan", "correct": true, "because": "Definiert Inhalte"}, {"text": "Prüfungsanforderungen", "correct": true, "because": "Legt Prüfungen fest"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Ausbildungsordnung ist gesetzlich bindend. b) Sie gilt nur für große Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Ausbildenden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Ausbildungsordnung?', 4, '[{"text": "Lernziele", "correct": false, "because": "Kern der Ordnung"}, {"text": "Prüfungsvorgaben", "correct": false, "because": "Teil der Regelung"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Ausbildungsordnung den Ausbildungsrahmenplan enthält?', 2, '[{"text": "Ja", "correct": true, "because": "Strukturiert Inhalte"}, {"text": "Nein", "correct": false, "because": "Teil der Ordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz bildet die Grundlage für die Ausbildungsordnung?', 3, '[{"text": "Berufsbildungsgesetz", "correct": true, "because": "Regelt Ausbildung"}, {"text": "Steuergesetz", "correct": false, "because": "Anderer Bereich"}, {"text": "Arbeitszeitgesetz", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Ausbildungsordnung?', 5, '[{"text": "Dauer der Ausbildung", "correct": true, "because": "Zeitlich festgelegt"}, {"text": "Lerninhalte", "correct": true, "because": "Definiert Ausbildung"}, {"text": "Produktwerbung", "correct": false, "because": "Kein Ausbildungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Ausbildungsordnung regelt Prüfungen. b) Sie ist für jeden Betrieb individuell. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einheitlich pro Beruf"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist in der Ausbildungsordnung unwichtig?', 4, '[{"text": "Ausbildungsziele", "correct": false, "because": "Kernbestandteil"}, {"text": "Prüfungsregelung", "correct": false, "because": "Wichtig"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Regelungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Ausbildungsordnung flexibel?', 2, '[{"text": "Nein", "correct": true, "because": "Gesetzlich festgelegt"}, {"text": "Ja", "correct": false, "because": "Einheitlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Ausbildungsordnung?', 4, '[{"text": "Einheitliche Standards", "correct": true, "because": "Gleicht Ausbildung"}, {"text": "Rechtssicherheit", "correct": true, "because": "Gesetzliche Basis"}, {"text": "Schnellere Abläufe", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Ausbildungsordnung nur für Auszubildende gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Ausbildende betroffen"}, {"text": "Ja", "correct": false, "because": "Beidseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in der Ausbildungsordnung?', 3, '[{"text": "Lerninhalte", "correct": true, "because": "Kern der Ausbildung"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Ausbildungsordnung legt die Dauer fest. b) Sie ist nur für Schulen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für Betriebe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine fehlende Ausbildungsordnung?', 5, '[{"text": "Uneinheitliche Ausbildung", "correct": true, "because": "Keine Standards"}, {"text": "Rechtsunsicherheit", "correct": true, "because": "Keine klare Basis"}, {"text": "Schnellere Ausbildung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist in der Ausbildungsordnung unwichtig?', 3, '[{"text": "Ausbildungsziele", "correct": false, "because": "Kernbestandteil"}, {"text": "Prüfungsvorgaben", "correct": false, "because": "Wichtig"}, {"text": "Betriebsausflüge", "correct": true, "because": "Kein Regelungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Regelt die Ausbildungsordnung Prüfungen?', 3, '[{"text": "Ja", "correct": true, "because": "Festlegung der Anforderungen"}, {"text": "Nein", "correct": false, "because": "Teil der Ordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Ausbildungsordnung die Ausbildungsdauer bestimmt?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzlich festgelegt"}, {"text": "Nein", "correct": false, "because": "Teil der Regelung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die Ausbildungsordnung?', 4, '[{"text": "Ausbildungsrahmenplan", "correct": true, "because": "Struktur der Inhalte"}, {"text": "Kostenplan", "correct": false, "because": "Kein Ausbildungsaspekt"}, {"text": "Betriebsdesign", "correct": false, "because": "Irrelevant"}]');
